#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;using U=uint64_t;using Rat=boost::multiprecision::cpp_rational;
map<U,U>ccache;map<U,pair<int,int>>atominfo;
U canonical(const vector<pair<int,int>>&ed){vector<int>vs;int dm[8]={};for(auto[a,b]:ed){vs.push_back(a);vs.push_back(b);dm[a]++;dm[b]++;}sort(vs.begin(),vs.end());vs.erase(unique(vs.begin(),vs.end()),vs.end());stable_sort(vs.begin(),vs.end(),[&](int a,int b){return dm[a]<dm[b];});int n=vs.size(),im[8][8]={},idx[8];for(int i=0;i<n;i++)idx[vs[i]]=i;for(auto[a,b]:ed)im[idx[a]][idx[b]]++,im[idx[b]][idx[a]]++;auto pack=[&](const vector<int>&p){U key=U(n)<<56;int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)key|=U(im[p[i]][p[j]])<<(2*k++);return key;};vector<int>p(n);iota(p.begin(),p.end(),0);U raw=pack(p);auto it=ccache.find(raw);if(it!=ccache.end())return it->second;vector<vector<int>>groups;for(int i=0;i<n;){vector<int>g;int j=i;while(j<n&&dm[vs[j]]==dm[vs[i]])g.push_back(j++);groups.push_back(g);i=j;}U best=raw;vector<U>orbit;function<void(int)>rec=[&](int k){if(k==(int)groups.size()){U z=pack(p);best=min(best,z);orbit.push_back(z);return;}auto g=groups[k];do{for(int j=0;j<(int)g.size();j++)p[groups[k][j]]=g[j];rec(k+1);}while(next_permutation(g.begin(),g.end()));};rec(0);for(U z:orbit)ccache[z]=best;atominfo[best]={n,(int)ed.size()};return best;}
vector<U>atoms(const vector<pair<int,int>>&ed){int mask=0;for(auto[a,b]:ed)mask|=(1<<a)|(1<<b);if(!mask)return {};for(int cut=0;cut<8;cut++)if(mask>>cut&1){int rem=mask^(1<<cut);vector<int>comps;while(rem){int s=rem&-rem;bool change=true;while(change){int old=s;for(auto[a,b]:ed)if(a!=cut&&b!=cut&&(((s>>a)&1)||((s>>b)&1)))s|=(1<<a)|(1<<b);change=s!=old;}comps.push_back(s);rem&=~s;}if(comps.size()>1){vector<U>out;for(int c:comps){int t=c|(1<<cut);vector<pair<int,int>>e;for(auto[a,b]:ed)if((t>>a&1)&&(t>>b&1))e.push_back({a,b});auto z=atoms(e);out.insert(out.end(),z.begin(),z.end());}sort(out.begin(),out.end());return out;}}return {canonical(ed)};}
bool onepi(int mask,const vector<pair<int,int>>&ed){if(__builtin_popcount((unsigned)mask)<2)return false;int low=mask&-mask;for(int s=(mask-1)&mask;s;s=(s-1)&mask){if(s&low)continue;int cross=0;for(auto[a,b]:ed)if((mask>>a&1)&&(mask>>b&1)&&((s>>a&1)!=(s>>b&1)))cross++;if(cross<2)return false;}return true;}
int findr(int*p,int a){while(a!=p[a])a=p[a];return a;}
void emitpoly(ostream&out,const map<vector<U>,Rat>&pol){out<<'[';bool first=true;for(auto&[key,v]:pol)if(v!=0){if(!first)out<<',';first=false;out<<"{\"monomial\":[";for(int j=0;j<(int)key.size();j++){if(j)out<<',';out<<'"'<<key[j]<<'"';}out<<"],\"coefficient\":\""<<v<<"\"}";}out<<']';}
int main(int argc,char**argv){string root=argv[1],output=argv[2];ofstream out(output),zero(output+".zero.json");out<<'{';zero<<'{';for(int L=1;L<=7;L++){if(L>1){out<<',';zero<<',';}ifstream in(root+"/classes"+to_string(L)+".txt");int n,NG;in>>n>>NG;vector<pair<int,int>>pairs;for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)pairs.push_back({a,b});map<vector<U>,Rat>A,B,BA,BB;vector<int>zeros;long long nf=0;for(int gi=0;gi<NG;gi++){U key;long long aut,orbit;in>>key>>aut>>orbit;int deg[8]={},fact[]={1,1,2,6,24},ss=0;long long den=aut;vector<pair<int,int>>ed;for(int k=0;k<(int)pairs.size();k++){int m=key>>(2*k)&3;den*=fact[m];auto[a,b]=pairs[k];for(int j=0;j<m;j++){ed.push_back({a,b});deg[a]++;deg[b]++;}}for(int i=0;i<n;i++){den*=fact[4-deg[i]];ss+=(4-deg[i])*(3-deg[i]);}Rat wa=Rat(24)/den,wb=wa*ss/12;auto aa=atoms(ed);BA[aa]+=wa;BB[aa]+=wb;
 vector<int>subs;int full=(1<<n)-1;for(int s=1;s<full;s++){int v=__builtin_popcount((unsigned)s),e=0;if(v<2)continue;for(auto[a,b]:ed)if((s>>a&1)&&(s>>b&1))e++;if(e==2*(v-1)&&onepi(s,ed))subs.push_back(s);}vector<vector<bool>>comp(subs.size(),vector<bool>(subs.size()));for(int i=0;i<(int)subs.size();i++)for(int j=0;j<(int)subs.size();j++){int a=subs[i],b=subs[j];comp[i][j]=((a&b)==a)||((a&b)==b)||(__builtin_popcount((unsigned)(a&b))<=1);}vector<int>sel;map<vector<U>,long long>poly;
 auto emit=[&](){nf++;vector<int>sets;for(int j:sel)sets.push_back(subs[j]);sets.push_back(full);vector<U>as;int he=0;bool valid=true;for(int P:sets){vector<int>ch;for(int s:sets)if(s!=P&&(s&P)==s){bool mx=true;for(int z:sets)if(z!=P&&z!=s&&(z&P)==z&&(s&z)==s){mx=false;break;}if(mx)ch.push_back(s);}int par[8];iota(par,par+8,0);for(int s:ch){int r=__builtin_ctz((unsigned)s);for(int i=0;i<n;i++)if(s>>i&1){int a=findr(par,r),b=findr(par,i);par[max(a,b)]=min(a,b);}}vector<pair<int,int>>qe;for(auto[a,b]:ed){if(!(P>>a&1)||!(P>>b&1))continue;bool inside=false;for(int s:ch)if((s>>a&1)&&(s>>b&1)){inside=true;break;}if(inside)continue;int x=findr(par,a),y=findr(par,b);if(x==y){valid=false;break;}qe.push_back({min(x,y),max(x,y)});}if(!valid)break;if(P==full)he=qe.size()/2;auto z=atoms(qe);as.insert(as.end(),z.begin(),z.end());}if(!valid||!he)return;sort(as.begin(),as.end());poly[as]+=(sel.size()%2?-he:he);};
 function<void(vector<int>)>rec=[&](vector<int>cand){emit();for(int k=0;k<(int)cand.size();k++){int j=cand[k];sel.push_back(j);vector<int>next;for(int u=k+1;u<(int)cand.size();u++)if(comp[j][cand[u]])next.push_back(cand[u]);rec(next);sel.pop_back();}};vector<int>all(subs.size());iota(all.begin(),all.end(),0);rec(all);bool nonzero=false;for(auto&[mon,v]:poly)if(v){nonzero=true;Rat c=v*(L%2?1:-1);A[mon]+=wa*c;B[mon]+=wb*c;}if(!nonzero)zeros.push_back(gi);if(gi%500==499)cerr<<L<<" graph "<<gi<<" cache "<<ccache.size()<<'\n';}
 out<<'"'<<L<<"\":{\"bareA\":";emitpoly(out,BA);out<<",\"bareB\":";emitpoly(out,BB);out<<",\"beta\":";emitpoly(out,A);out<<",\"gamma\":";emitpoly(out,B);out<<",\"forest_count\":"<<nf<<'}';zero<<'"'<<L<<"\":[";for(int j=0;j<(int)zeros.size();j++){if(j)zero<<',';zero<<zeros[j];}zero<<']';cerr<<"L "<<L<<" completed graphs "<<NG<<" forests "<<nf<<" cache "<<ccache.size()<<" zero "<<zeros.size()<<'\n';}out<<'}';zero<<'}';}
